import {escapeHtml as esc,formatNumber as fmt} from './map-logic.mjs';
import {displayDate} from './globe-math.mjs';
import {filterMarket,statuses} from './market-logic.mjs';
const icons={globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',external:'<path d="M14 4h6v6M20 4 10 14M11 5H5v14h14v-6"/>',pause:'<path d="M9 5v14M15 5v14"/>',play:'<path d="m8 5 11 7-11 7Z"/>',rotate:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',list:'<path d="M8 6h12M8 12h12M8 18h12M4 6h.1M4 12h.1M4 18h.1"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
let engine,data,selectedId=null,view='deals',limit=50;
const filter={region:'Deutschland',sector:'all',status:'all',query:''};
const app=document.getElementById('app');
app.innerHTML=`<header class="topbar"><a class="brand" href="/" aria-label="Marktatlas Startseite"><span class="brand-icon">${icon('globe')}</span>marktatlas<span class="brand-dot">.</span><span class="orbit-badge">ORBIT</span></a><nav aria-label="Kartenansicht"><span aria-current="page">3D-Globus</span><a href="/deutschland/">Deutschland</a><a href="/karte/">2D-Karte</a></nav><button id="sources" class="sources-button">${icon('info')}<span>Daten & Quellen</span></button></header>
<div class="workspace"><aside class="sidebar"><div class="overview"><p class="eyebrow">Deutschland zuerst · 2026</p><h1>Wer kauft <em>wen?</em></h1><div class="stats-line"><strong id="deal-count">—</strong><span id="count-label">Kaufbeziehungen</span><button id="open-deals" class="mobile-deals" aria-label="Ergebnisliste öffnen">${icon('list')}</button></div><div class="market-filters"><label>Region<select id="region-filter"><option>Deutschland</option></select></label><label>Branche<select id="industry-filter"><option value="all">Alle Branchen</option></select></label><label>Status<select id="status-filter"><option value="all">Alle Status</option><option value="completed">Abgeschlossen</option><option value="pending">Angebot / vereinbart</option><option value="interest">Kaufabsicht</option><option value="listed">Börseneinträge</option></select></label><label>Suche<input id="company-search" type="search" placeholder="Unternehmen oder ISIN" autocomplete="off"></label></div><div class="view-tabs" aria-label="Ergebnisart"><button data-view="deals" aria-pressed="true">Kaufbeziehungen</button><button data-view="companies" aria-pressed="false">Unternehmen & Aktien</button></div><p id="coverage-summary" aria-live="polite"></p></div><div class="deal-list" id="deal-list" aria-label="Gefilterte Ergebnisse"></div><div class="sidebar-note"><span class="coverage-mark">◐</span><p>Keine vollständige Übernahmeliste. Fehlende Branchen und Standorte bleiben sichtbar als ungeklärt.</p></div></aside>
<section class="space" aria-label="Erde und Kaufbeziehungen"><div id="globe"></div><div class="space-top"><div class="direction-key"><span>→ Käufer zum Ziel</span><span class="status-key complete">● Abschluss</span><span class="status-key pending">┄ Angebot</span><span class="status-key interest">┄ Absicht</span><span class="status-key listed">● Börse*</span></div></div><div class="loading" id="loading" role="status"><span class="spinner"></span>Der Globus wird geladen …</div><div class="scene-notice" id="scene-notice" role="status" hidden></div><div class="endpoint-label buyer-label" id="buyer-label" hidden></div><div class="endpoint-label target-label" id="target-label" hidden></div><div class="hover-tooltip" id="hover-tooltip" hidden></div><section class="selection-card" id="selection-card" aria-label="Ausgewählter Eintrag" tabindex="-1" hidden></section><label class="companies-toggle"><input id="companies-toggle" type="checkbox" checked><span class="checkbox-ui"></span><span><b id="site-count">—</b> Standorte anzeigen</span></label><div class="globe-controls"><button id="zoom-in" aria-label="Hineinzoomen">${icon('plus')}</button><button id="zoom-out" aria-label="Herauszoomen">${icon('minus')}</button><button id="germany" aria-label="Deutschland zentrieren" title="Deutschland">DE</button><button id="home" aria-label="Weltansicht" title="Weltansicht">${icon('globe')}</button><button id="rotation" aria-pressed="false" aria-label="Globusrotation starten">${icon('play')}</button></div><div class="touch-hint">Ziehen zum Drehen · zwei Finger zum Zoomen</div></section></div>
<footer><span>Stand 06.09.2026 · Auswahl, keine vollständige Marktabdeckung</span><span>NASA Earth 3D · *Börsenreferenzen, keine Handelsumsätze</span></footer>
<dialog id="sources-dialog" aria-labelledby="sources-title"><div class="dialog-top"><h2 id="sources-title">Daten & Quellen</h2><button class="icon-button" data-close-dialog aria-label="Quellen schließen">${icon('close')}</button></div><p class="dialog-lead">Grüne Pfeile zeigen belegte Abschlüsse. Orange gestrichelte Pfeile zeigen Angebote oder vereinbarte Käufe vor dem Vollzug. Violett zeigt eine belegte Kaufabsicht. Die Richtung ist immer Käufer → Ziel.</p><div class="source-note"><strong id="source-summary"></strong><p>Keine vollständige Deutschland- oder Weltliste: Insbesondere private Unternehmenskäufe und nicht veröffentlichte Verhandlungen sind nicht vollständig erfasst. Ein fehlender Pfeil beweist nicht, dass kein Kauf stattfindet.</p></div><dl><div><dt>Deutschland und Börsenhandel</dt><dd>Deutschland zeigt erfasste Standorte in Deutschland sowie DE-ISIN-Aktien ohne geklärten Sitz. Eine deutsche ISIN allein beweist keinen deutschen Hauptsitz. Bekannte ausländische Hauptsitze bleiben der jeweiligen Region zugeordnet. Eine Handelsreferenz belegt Handelbarkeit laut Quelle, keine tatsächlich ausgeführten Geschäfte. Der ergänzte Xetra-Download wurde am 06.09. abgerufen und trägt bereits den Referenzstand 07.09.2026. Ältere Wikidata-Notierungen sind ausdrücklich ungeprüft.</dd></div><div><dt>Datum und Status</dt><dd>Bei Abschlüssen steht das Vollzugsdatum; bei offenen Vorhaben das Ankündigungsdatum. Der Quellenstand steht in den Details. Eine abgelaufene Annahmefrist wird niemals automatisch zum Abschluss. Käufe von Geschäftsteilen und Mehrheitsbeteiligungen sind eigens gekennzeichnet.</dd></div><div><dt>Branchen</dt><dd>Wikidata-Branchen, Unternehmensbeschreibungen und einzelne Unternehmensquellen werden zu übersichtlichen Branchengruppen zusammengefasst. Das ist keine offizielle GICS- oder WZ-Klassifikation. Mehrfachzuordnungen sind möglich. „Nicht zugeordnet“ bedeutet fehlende belastbare Angaben. Der Branchenfilter bei Pfeilen berücksichtigt Käufer oder Ziel; bei Einträgen die eigene Branche.</dd></div><div><dt>Standorte und Vollständigkeit</dt><dd>Koordinaten stammen aus Quellen, oft nur aus dem Ort des Hauptsitzes. Nicht zugeordnete Aktienpositionen erscheinen ausschließlich in der Liste. Mehrere Aktiengattungen werden nur bei eindeutiger Unternehmenszuordnung zusammengeführt. Erfasste Hauptsitze sind keine Prüfung des historischen juristischen Sitzes. Bei Käufen über Tochtergesellschaften kann die ausdrücklich benannte Käufergruppe angezeigt werden.</dd></div><div><dt>Darstellung</dt><dd>Pfeilgröße und Bogenhöhe haben keine finanzielle Bedeutung. Nahe beieinander liegende Endpunkte werden nicht geografisch verschoben. Unternehmen am selben Ort öffnen eine Auswahlliste. NASA Earth 3D von VTAD ist ein festes Modell, keine Live-Aufnahme oder Gebäudekarte.</dd></div></dl><div class="source-links"><a href="https://www.cashmarket.deutsche-boerse.com/cash-en/trading/Tradable-Instruments-Xetra/Downloads" target="_blank" rel="noopener noreferrer">Deutsche Börse · Xetra-Handelsreferenz ${icon('external')}</a><a href="https://www.wikidata.org/" target="_blank" rel="noopener noreferrer">Wikidata · Standorte und Branchen ${icon('external')}</a><a href="https://science.nasa.gov/resource/earth-3d-model/" target="_blank" rel="noopener noreferrer">NASA · Earth 3D ${icon('external')}</a></div><h3>Quellen der Kaufbeziehungen</h3><div id="deal-sources" class="source-links"></div></dialog>
<dialog id="deals-dialog" aria-labelledby="deals-title"><div class="dialog-top"><h2 id="deals-title">Ergebnisse</h2><button class="icon-button" data-close-dialog aria-label="Ergebnisse schließen">${icon('close')}</button></div><div id="mobile-deal-list" class="deal-list"></div></dialog>
<dialog id="companies-dialog" aria-labelledby="companies-title"><div class="dialog-top"><h2 id="companies-title">Unternehmen am selben Ort</h2><button class="icon-button" data-close-dialog aria-label="Unternehmensliste schließen">${icon('close')}</button></div><div id="company-list"></div></dialog>`;
const $=id=>document.getElementById(id),card=$('selection-card');
const kindLabel=d=>({company:'Unternehmenskauf',majority:'Mehrheitsbeteiligung',business:'Geschäftsbereich'}[d.kind]);
const statusLabel=d=>statuses[d.status]?.label||'Ungeklärt';
const statusStyle=d=>`--status-color:${statuses[d.status]?.css||'#85caff'}`;
const listingLabel=c=>({reference:'Xetra-Referenz 07.09.2026',reported:'Börsennotierung laut Meldung',unverified:'Börsennotierung ungeprüft',not_recorded:'Keine Börsenangabe erfasst'}[c.listingStatus]);
const sectorText=c=>(c.sectors||['Nicht zugeordnet']).join(' · ');
const safeSource=c=>c.sourceUrl||c.locationSourceUrl;
function notice(s){$('scene-notice').textContent=s;$('scene-notice').hidden=false;}
function rotationState(on){$('rotation').innerHTML=icon(on?'pause':'play');$('rotation').setAttribute('aria-pressed',String(on));$('rotation').setAttribute('aria-label',on?'Rotation pausieren':'Rotation starten');}
function clearSelection(){selectedId=null;card.hidden=true;engine?.selectDeal(null,false);document.querySelector('.space').classList.remove('has-selection');$('buyer-label').hidden=true;$('target-label').hidden=true;document.querySelectorAll('[data-deal]').forEach(b=>b.classList.remove('selected'));}
function revealCard(){card.hidden=false;document.querySelector('.space').classList.add('has-selection');$('close-selection').addEventListener('click',clearSelection);card.focus({preventScroll:true});}
function dealRow(d){const b=data.entities[d.buyerId],t=data.entities[d.targetId];return `<button class="deal-row status-row" style="${statusStyle(d)}" data-deal="${esc(d.id)}"><span class="deal-route"><span class="status-badge">${statusLabel(d)}</span><strong>${esc(b.name)}</strong><span>${icon('arrow')}${esc(t.name)}</span><small class="deal-geography">${esc(sectorText(t))}<br>${esc(b.country)} → ${esc(t.country)}</small></span><span class="deal-meta">${d.status==='completed'?'Abschluss':'Ankündigung'}<br>${displayDate(d.date)}<span class="deal-arrow">↗</span></span></button>`;}
function companyRow(c){return `<button class="deal-row company-row" data-company="${esc(c.id)}"><span class="deal-route"><strong>${esc(c.name)}</strong><span>${esc(sectorText(c))}</span><small class="deal-geography">${c.location?esc(c.location.name)+' · '+esc(c.location.country):'Standort ungeklärt · nur Listeneintrag'}<br>${esc(listingLabel(c))}${c.recordType==='instrument'?' · Aktienposition':''}</small></span><span class="deal-arrow">↗</span></button>`;}
function attachRows(root){root.querySelectorAll('[data-deal]').forEach(b=>b.addEventListener('click',()=>{$('deals-dialog').close();selectDeal(b.dataset.deal);}));root.querySelectorAll('[data-company]').forEach(b=>b.addEventListener('click',()=>{$('deals-dialog').close();$('companies-dialog').close();showCompany(data.companies.find(c=>c.id===b.dataset.company));}));root.querySelectorAll('[data-more]').forEach(b=>b.addEventListener('click',()=>{limit+=50;render(false);}));}
function render(updateMap=true){
 const found=filterMarket(data,filter),rows=view==='deals'?found.deals:found.companies;
 const html=rows.length?rows.slice(0,limit).map(view==='deals'?dealRow:companyRow).join('')+(rows.length>limit?`<button class="load-more" data-more>${fmt(Math.min(50,rows.length-limit))} weitere anzeigen (${fmt(rows.length-limit)} verbleibend)</button>`:''):'<p class="empty-note">Keine passenden Einträge im erfassten Bestand. Das ist kein Nachweis, dass es keine solchen Unternehmen oder Käufe gibt.</p>';
 for(const id of ['deal-list','mobile-deal-list']){$(id).innerHTML=html;attachRows($(id));}
 $('deal-count').textContent=fmt(rows.length);$('count-label').textContent=view==='deals'?'Kaufbeziehungen':'Unternehmens-/Aktieneinträge';$('deals-title').textContent=view==='deals'?'Kaufbeziehungen':'Unternehmen & Aktien';
 const unlocated=found.companies.filter(c=>!c.location).length;
 $('coverage-summary').textContent=`${found.deals.length} Beziehungen · ${fmt(found.companies.length)} Einträge${unlocated?' · '+unlocated+' ohne Standort':''} · Bestand unvollständig`;
 document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));
 if(updateMap&&engine){
  engine.filterDeals(found.deals.map(d=>d.id));const colors=new Map();
  // More uncertain status takes priority for company points; arrows retain their individual status.
  for(const status of ['completed','pending','interest'])for(const d of found.deals.filter(d=>d.status===status))for(const id of [d.buyerId,d.targetId])colors.set(id,statuses[status].color);
  const points=found.companies.filter(c=>c.location).map(c=>({...c,pointColor:colors.get(c.id)||0x85caff}));engine.setCompanies(points);engine.showCompanies($('companies-toggle').checked);$('site-count').textContent=fmt(points.length);
 }
}
function selectDeal(id){clearSelection();const d=data.deals.find(d=>d.id===id);if(!d)return;
 if(!filterMarket(data,filter).deals.some(x=>x.id===id)){Object.assign(filter,{region:'all',sector:'all',status:'all',query:''});$('region-filter').value='all';$('industry-filter').value='all';$('status-filter').value='all';$('company-search').value='';limit=50;render();}
 selectedId=id;engine?.selectDeal(id);const b=data.entities[d.buyerId],t=data.entities[d.targetId];
 card.innerHTML=`<div class="card-top"><span class="status-badge" style="${statusStyle(d)}">${statusLabel(d)} · ${kindLabel(d)}</span><button class="icon-button" id="close-selection" aria-label="Details schließen">${icon('close')}</button></div><div class="deal-relationship"><div><span class="endpoint-role">${d.status==='completed'?'KÄUFER':'VORGESEHENER KÄUFER'}</span><h2>${esc(b.name)}</h2><p class="sector-tag">${esc(sectorText(b))}</p><a class="place-link" href="${esc(b.locationSourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(b.place)} · ${esc(b.country)}</a></div><span class="relationship-arrow" style="color:${statuses[d.status].css}">${icon('arrow')}</span><div><span class="endpoint-role">${d.status==='completed'?'ÜBERNOMMEN':'KAUFZIEL'}</span><h2>${esc(t.name)}</h2><p class="sector-tag">${esc(sectorText(t))}</p><a class="place-link" href="${esc(t.locationSourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(t.place)} · ${esc(t.country)}</a></div></div><p class="deal-note">${d.status==='completed'?'Abschluss':'Ankündigung'}: ${displayDate(d.date)} · Quellenstand: ${displayDate(d.statusAsOf||d.date)}</p>${d.note?`<p class="deal-note">${esc(d.note)}</p>`:''}<div class="card-bottom"><span>Standorte teils nur ortsgenau</span><a href="${esc(d.sourceUrl)}" target="_blank" rel="noopener noreferrer">Statusquelle öffnen ${icon('external')}</a></div>`;
 revealCard();document.querySelectorAll('[data-deal]').forEach(b=>b.classList.toggle('selected',b.dataset.deal===id));
}
function showCompany(c){if(!c)return;clearSelection();if(c.location)engine?.focusLocation(c.location.lat,c.location.lon,115);const related=data.deals.filter(d=>d.buyerId===c.id||d.targetId===c.id);
 card.innerHTML=`<div class="card-top"><span class="eyebrow">${c.recordType==='instrument'?'Aktienposition · Emittent ungeklärt':'Unternehmen'}</span><button class="icon-button" id="close-selection" aria-label="Details schließen">${icon('close')}</button></div><h2 class="company-name">${esc(c.name)}</h2><p class="sector-tag">${esc(sectorText(c))}</p><p class="company-place">${c.location?esc(c.location.name)+' · '+esc(c.location.country):'Kein belegter Standort zugeordnet; deshalb kein Kartenpunkt.'}</p><div class="company-listings">${c.listings.map(l=>`<span>${esc(l.exchange)}${l.ticker?' · '+esc(l.ticker):''}${l.isin?' · '+esc(l.isin):''}</span>`).join('')}</div><p class="deal-note">${esc(listingLabel(c))}. Branchenbasis: ${esc(c.industryBasis)}.${c.industryLabels?.length?' Erfasste Branchen: '+esc(c.industryLabels.join(', '))+'.':''}</p>${c.industrySourceUrl?`<a class="industry-source" href="${esc(c.industrySourceUrl)}" target="_blank" rel="noopener noreferrer">Branchenquelle</a>`:''}<div class="related-deals">${related.length?related.map(d=>`<button data-deal="${esc(d.id)}" class="related-deal" style="${statusStyle(d)}">${statusLabel(d)}: ${esc(data.entities[d.buyerId].name)} → ${esc(data.entities[d.targetId].name)}</button>`).join(''):'<p class="deal-note">Keine Kaufbeziehung in diesem Bestand erfasst.</p>'}</div><div class="card-bottom"><span>${c.deIsin?'DE-ISIN ist kein Sitznachweis':'Angaben laut erfassten Quellen'}</span><a href="${esc(safeSource(c))}" target="_blank" rel="noopener noreferrer">Quelle öffnen ${icon('external')}</a></div>`;
 revealCard();attachRows(card);
}
function companyClick(records){if(records.length===1){showCompany(records[0]);return;}$('companies-title').textContent=`${records[0].location.name}: ${records.length} Unternehmen`;$('company-list').innerHTML=records.map(companyRow).join('');attachRows($('company-list'));$('companies-dialog').showModal();}
function labels(items){const d=data?.deals.find(d=>d.id===selectedId);for(const role of ['buyer','target']){const el=$(role+'-label'),item=items.find(i=>i.role===role);if(!item?.visible||!d){el.hidden=true;continue;}el.hidden=false;el.innerHTML=`<small>${role==='buyer'?'KÄUFER':d.status==='completed'?'ÜBERNOMMEN':'KAUFZIEL'}</small><b>${esc(item.entity.name)}</b>`;const x=Math.max(12,Math.min($('globe').clientWidth-el.offsetWidth-12,item.x+16));el.style.transform=`translate(${x}px,${Math.max(70,item.y-35)}px)`;}}
function hover(d,x,y){const el=$('hover-tooltip');if(!d){el.hidden=true;return;}const r=$('globe').getBoundingClientRect();el.innerHTML=`<strong>${esc(data.entities[d.buyerId].name)} → ${esc(data.entities[d.targetId].name)}</strong><span>${statusLabel(d)} · ${displayDate(d.date)}</span>`;el.hidden=false;el.style.left=`${Math.max(12,Math.min(r.width-280,x-r.left+16))}px`;el.style.top=`${Math.max(65,y-r.top-65)}px`;}
function navigate(){if(filter.region==='Deutschland')engine?.germany();else if(filter.region==='all')engine?.home();else{const centers={Europa:[50,12],Nordamerika:[35,-100],Südamerika:[-15,-60],Afrika:[-5,25],Asien:[25,100],Ozeanien:[-25,135]};engine?.focusLocation(...centers[filter.region],255);}}
function resetRegion(region){filter.region=region;$('region-filter').value=region;clearSelection();if(data)render();navigate();}
$('region-filter').addEventListener('change',e=>resetRegion(e.target.value));$('industry-filter').addEventListener('change',e=>{filter.sector=e.target.value;limit=50;clearSelection();if(data)render();});$('status-filter').addEventListener('change',e=>{filter.status=e.target.value;if(filter.status==='listed')view='companies';limit=50;clearSelection();if(data)render();});let searchTimer;$('company-search').addEventListener('input',e=>{filter.query=e.target.value.trim();clearTimeout(searchTimer);searchTimer=setTimeout(()=>{limit=50;clearSelection();if(data)render();},140);});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;limit=50;if(data)render(false);}));
$('germany').addEventListener('click',()=>resetRegion('Deutschland'));$('home').addEventListener('click',()=>resetRegion('all'));$('zoom-in').addEventListener('click',()=>engine?.zoom(.84));$('zoom-out').addEventListener('click',()=>engine?.zoom(1.19));$('rotation').addEventListener('click',()=>engine?.toggleRotation());$('companies-toggle').addEventListener('change',e=>engine?.showCompanies(e.target.checked));$('sources').addEventListener('click',()=>$('sources-dialog').showModal());$('open-deals').addEventListener('click',()=>$('deals-dialog').showModal());document.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]'))clearSelection();});
async function load(){const jobs=await Promise.allSettled([fetch('/assets/market-data.json').then(r=>{if(!r.ok)throw Error('data');return r.json();}),import('./globe-scene.js')]);if(jobs[0].status!=='fulfilled'){$('loading').innerHTML='<strong>Daten konnten nicht geladen werden.</strong><button onclick="location.reload()">Erneut laden</button>';return;}data=jobs[0].value;
 $('region-filter').innerHTML=['Deutschland','all','Europa','Nordamerika','Südamerika','Afrika','Asien','Ozeanien'].map(r=>`<option value="${r}">${r==='all'?'Weltweit':r}</option>`).join('');$('industry-filter').innerHTML='<option value="all">Alle Branchen</option>'+[...new Set(data.companies.flatMap(c=>c.sectors))].sort((a,b)=>a.localeCompare(b,'de')).map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');
 $('source-summary').textContent=`${data.meta.verifiedDealCount} Abschlüsse, ${data.meta.pendingCount} offene Angebote/Vereinbarungen und ${data.meta.interestCount} Kaufabsicht. ${data.meta.deIsinInstrumentCount} DE-ISIN-Aktienpositionen aus der Xetra-Referenz.`;
 $('deal-sources').innerHTML=data.deals.map(d=>`<a href="${esc(d.sourceUrl)}" target="_blank" rel="noopener noreferrer"><span>${esc(data.entities[d.buyerId].name)} → ${esc(data.entities[d.targetId].name)}<small>${statusLabel(d)} · ${displayDate(d.date)}</small></span>${icon('external')}</a>`).join('');render(false);
 try{if(jobs[1].status!=='fulfilled')throw jobs[1].reason;engine=jobs[1].value.createGlobe($('globe'),{onDealClick:selectDeal,onCompanyClick:companyClick,onNotice:notice,onError:notice,onRotation:rotationState,onLabels:labels,onHover:hover,onView:d=>{$('zoom-in').disabled=d<=101.51;$('zoom-out').disabled=d>=589.9;}});engine.setDeals(data.deals,data.entities);render();navigate();$('loading').hidden=true;}catch(e){$('loading').innerHTML='<strong>3D ist auf diesem Gerät nicht verfügbar.</strong><span>Alle Einträge bleiben über die Liste erreichbar.</span><a href="/karte/">2D-Karte öffnen</a>';document.querySelectorAll('.globe-controls button').forEach(b=>b.disabled=true);}}
await load();
